UNITS = [{'id': 'PEDS-U076', 'ch': 9, 'n': 1, 'title': 'Microcephaly — Definitions and Primary Etiology', 'sec': 'Microcephaly · p41', 'qs': ['PEDS-C9-001', 'PEDS-C9-002', 'PEDS-C9-003', 'PEDS-C9-004', 'PEDS-C9-005', 'PEDS-C9-006', 'PEDS-C9-007', 'PEDS-C9-008', 'PEDS-C9-009', 'PEDS-C9-010', 'PEDS-C9-011', 'PEDS-C9-012', 'PEDS-C9-013', 'PEDS-C9-014', 'PEDS-C9-015', 'PEDS-C9-016'], 'guide': 'Small brain. HC <-2SD low, <-3SD severe/pathological. Primary: defective brain development—Trisomy 21/18/13, Cornelia de Lange (synorphys), Rubinstein-Taybi (broad thumb), familial AR.'}, {'id': 'PEDS-U077', 'ch': 9, 'n': 2, 'title': 'Secondary Microcephaly and PKU Pathway', 'sec': 'Secondary · p41', 'qs': ['PEDS-C9-017', 'PEDS-C9-018', 'PEDS-C9-019', 'PEDS-C9-020', 'PEDS-C9-021', 'PEDS-C9-022', 'PEDS-C9-023', 'PEDS-C9-024', 'PEDS-C9-025', 'PEDS-C9-026', 'PEDS-C9-027', 'PEDS-C9-028'], 'guide': 'External factors: maternal TORCH/alcohol/Phenytoin/radiation, perinatal asphyxia, trauma/infection, PKU (phenylalanine hydroxylase deficiency → ↓tyrosine→↓melanin→hypopigmentation; phenylacetate etc → mousy urine → brain damage/microcephaly).'}, {'id': 'PEDS-U078', 'ch': 9, 'n': 3, 'title': 'Microcephaly d/t Teratogens', 'sec': 'Microcephaly d/t Teratogens · p42', 'qs': ['PEDS-C9-029', 'PEDS-C9-030', 'PEDS-C9-031', 'PEDS-C9-032', 'PEDS-C9-033', 'PEDS-C9-034', 'PEDS-C9-035', 'PEDS-C9-036', 'PEDS-C9-037'], 'guide': 'Fetal alcohol syndrome: microcephaly, FAS facies (small eyes, smooth philtrum, thin upper lip), m/c VSD. Fetal hydantoin (phenytoin): cleft lip/palate, microcephaly, cardiac defects, hypoplasia nails/phalanges.'}, {'id': 'PEDS-U079', 'ch': 9, 'n': 4, 'title': 'Late Onset Acquired Syndromes and Macrocephaly Definition', 'sec': 'Late onset syndromes · p42', 'qs': ['PEDS-C9-038', 'PEDS-C9-039', 'PEDS-C9-040', 'PEDS-C9-041', 'PEDS-C9-042', 'PEDS-C9-043', 'PEDS-C9-044', 'PEDS-C9-045', 'PEDS-C9-046', 'PEDS-C9-047', 'PEDS-C9-048', 'PEDS-C9-049', 'PEDS-C9-050', 'PEDS-C9-051'], 'guide': 'Rett (X-linked dominant MECP2, normal → microcephaly after 1y, regression, hand-wringing midline, ataxia), Seckel (bird/beak nose), Angelman. Macrocephaly: HC >+2SD. Causes: fluid/hydrocephalus, hydranencephaly transillumination+.'}, {'id': 'PEDS-U080', 'ch': 9, 'n': 5, 'title': 'Macrocephaly — Thick Skull and Brain Volume Introduction', 'sec': 'Macrocephaly · p43', 'qs': ['PEDS-C9-052', 'PEDS-C9-053', 'PEDS-C9-054', 'PEDS-C9-055', 'PEDS-C9-056'], 'guide': 'Thick skull: hemolytic anemia→extramedullary hematopoiesis (β-thal major) + achondroplasia/osteopetrosis. Brain volume ↑ megalencephaly introduction → lysosomal, leukodystrophy, genetic.'}, {'id': 'PEDS-U081', 'ch': 9, 'n': 6, 'title': 'Megalencephaly — Metabolic and Genetic Causes', 'sec': 'Megalencephaly · p43', 'qs': ['PEDS-C9-057', 'PEDS-C9-058', 'PEDS-C9-059', 'PEDS-C9-060', 'PEDS-C9-061', 'PEDS-C9-062', 'PEDS-C9-063', 'PEDS-C9-064', 'PEDS-C9-065', 'PEDS-C9-066', 'PEDS-C9-067', 'PEDS-C9-068'], 'guide': 'Lysosomal: Tay-Sachs (Hex A, cherry spot, no HSM) vs Sandhoff (Hex A&B, +HSM). Leukodystrophies: Alexander/Canavan. Genetic: Sotos/cerebral gigantism, NF1, Fragile X CGG repeats (long face, large ears, macroorchidism). Familial m/c cause.'}, {'id': 'PEDS-U082', 'ch': 9, 'n': 7, 'title': 'Craniosynostosis — Basics and Sutures', 'sec': 'Craniosynostosis · p43', 'qs': ['PEDS-C9-069', 'PEDS-C9-070', 'PEDS-C9-071', 'PEDS-C9-072', 'PEDS-C9-073'], 'guide': 'Cranio=skull, synostosis=fusion → premature. Normal: metopic <2y, coronal/sagittal/lambdoid <2nd decade. Rule: growth arrests perpendicular to fused suture, proceeds parallel.'}, {'id': 'PEDS-U083', 'ch': 9, 'n': 8, 'title': 'Craniosynostosis — Types', 'sec': 'Types · p44', 'qs': ['PEDS-C9-074', 'PEDS-C9-075', 'PEDS-C9-076', 'PEDS-C9-077', 'PEDS-C9-078', 'PEDS-C9-079', 'PEDS-C9-080', 'PEDS-C9-081'], 'guide': '1 Dolico/scapho m/c sagittal → AP expansion. 2 Brachy B/L coronal → transverse elongation. 3 Plagio U/L coronal → flat side + U/L elongation. 4 Trigono metopic → anterior elongation. 5 Oxy/Turri multiple → irregular.'}, {'id': 'PEDS-U084', 'ch': 9, 'n': 9, 'title': 'Craniosynostosis — Syndromes', 'sec': 'Associated syndromes · p44', 'qs': ['PEDS-C9-082', 'PEDS-C9-083', 'PEDS-C9-084', 'PEDS-C9-085', 'PEDS-C9-086', 'PEDS-C9-087', 'PEDS-C9-088', 'PEDS-C9-089', 'PEDS-C9-090', 'PEDS-C9-091', 'PEDS-C9-092', 'PEDS-C9-093', 'PEDS-C9-094'], 'guide': 'Crouzon (AD, brachy, shallow orbit→exophthalmos/hypertelorism/maxillary hypoplasia, normal IQ, tower skull) vs Apert (AD, turricephaly, syndactyly mitten hand, low IQ, exophthalmos not prominent). Carpenter AR similar to Apert + obesity/hypogonadism.'}]
